const STARTER_PIN_PRIORITY = Object.freeze([
  Object.freeze(['hearthstone']),
  Object.freeze(['potion_mana', 'mana_potion']),
  Object.freeze(['potion_health', 'healing_potion']),
]);

const STARTER_PIN_SKIP_IDENTITIES = new Set([
  'scroll_identify',
